      "She helped me out in a very practical way. Instead of simply doing the assignment for me, she asked me to show each step and pointed out where I had selected the wrong data range. She also explained why the graph looked strange and asked me to repeat the process once more by myself.",
      "After that, I realised asking for help is not a sign of weakness. It can actually save time and help you learn faster, as long as you stay involved. I still had to finish the assignment myself, but her feedback gave me the confidence to continue.",
