      "建筑和商家也应该承担责任。更好的隔音、限制夜间施工，以及更严格管理大声播放广告喇叭，都会有很大帮助。在个人层面，人们可以在共享空间压低声音，并避免在公共场所大声放音乐。噪音看起来可能没有空气污染严重，但它会扰乱睡眠、专注力和心理健康，所以城市应该把它当成真正的健康问题来处理。",
