      "不过，竞争并不总是好事。如果人们把所有事情都看成零和游戏，他们可能会停止分享想法，变得焦虑或自私。在极端情况下，持续比较可能导致倦怠，尤其是对那些觉得自己每件事都必须最优秀的学生来说。我认为最健康的竞争，是人们努力提升自己，同时仍然尊重他人。竞争应该鼓励进步，而不是破坏合作或心理健康。",
