      "不过，成功还包括个人满足感、人际关系和社会贡献。一个人可以很富有，但很孤独、不健康，或者对自己赚钱的方式感到羞愧。同时，老师、护士或志愿者可能并不特别富有，但他们的工作可以很有意义，也值得尊重。所以我会用一个人是否拥有足够安全感、目标感，以及是否对他人产生积极影响来衡量成功，而不只是看收入。",
