      "如今，媒体接触也扮演着重要角色。新闻、网红和算法可以决定人们每天看到什么信息，而这可能导致确认偏误。同伴压力也很重要，尤其是对想融入群体的青少年和年轻成年人来说。我不认为人们形成观点的过程完全理性。我们大多数人都会受到情绪、身份认同和周围人的影响，即使我们相信自己很独立。",
