      "和当地人的互动很重要，因为它提醒旅行者，一个目的地是某些人的家，而不只是拍照背景。和居民聊天、尊重地尝试当地食物，或者了解一点历史，都能开阔眼界。有时最难忘的部分并不是大型景点，而是一段对话、一条安静的街道，或者一个让你跳出日常、以不同方式看待生活的时刻。对我来说，这才是旅行有意义的地方。",
