      "不过，单靠惩罚不够。执法必须持续一致，否则规则只会停留在纸面上。政府还应该提供预防措施，比如定期检查、透明报告，以及对清洁技术的支持。对于个人来说，在某些情况下，教育和便利的回收系统可能比惩罚更有效。所以我支持对严重污染者，尤其是企业，进行更严格处罚，但它应该是一个更大系统的一部分，在污染发生前就加以预防。",
